REACHED: set[str] = set()
#: Where each launcher global the two call is defined; a body that went past the launcher would reach one of these.
HOMES = {board_services: ("_board_system_unit", "_board_system_unit_action", "_listener_user_unit", "board_system_unit_is_active",
                          "capture_listener_state", "start_owner_listener", "stop_owner_listener"),
         presentation_windows: ("close_presentation_window",), residual_processes: ("contain_residual_project_processes",),
         staged_role_tooling: ("ensure_staged_role_tooling",)}

CONFIG = SimpleNamespace(project="atlas")
CONFIG_PATH = Path("/nonexistent/syrd405/atlas.json")
PROC = Path("/nonexistent/syrd405/proc")


def RUNNER(*args: object, **kwargs: object) -> object:
    raise AssertionError("the runner is only passed on")


def SIGNALLER(*args: object, **kwargs: object) -> object:
    raise AssertionError("the signaller is only passed on")


NAMES = {id(RUNNER): "RUNNER", id(SIGNALLER): "SIGNALLER", id(subprocess.run): "subprocess.run", id(os.kill): "os.kill", id(builtins.print): "print"}
BASE = {"_board_system_unit": "atlas-board.service", "_listener_user_unit": "atlas-listener.service"}


def check(condition: bool, detail: str) -> None:
    global CHECKS
    assert condition, detail
    CHECKS += 1


def python(probe: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run([sys.executable, "-c", probe], cwd=ROOT, capture_output=True, text=True,
                          env={"PATH": "/usr/bin:/bin"}, check=False)


class patched:
    def __init__(self, target: object, **values: object) -> None:
        self.target, self.values = target, values

    def __enter__(self) -> None:
        self.saved = {name: getattr(self.target, name) for name in self.values}
        for name, value in self.values.items():
            setattr(self.target, name, value)

    def __exit__(self, *exc: object) -> None:
        for name, value in self.saved.items():
            setattr(self.target, name, value)


def refuse(what: str):
    def refused(*args: object, **kwargs: object) -> object:
        raise AssertionError(f"{what} was called: {args} {kwargs}")
    return refused


class contained:
    """The real process spawn and signal refused, and every step's own definition, so only the launcher's stand-ins can answer."""

    def __enter__(self) -> None:
        self.parts = [patched(subprocess, run=refuse("subprocess.run"), Popen=refuse("subprocess.Popen")), patched(os, kill=refuse("os.kill")),
                      *(patched(home, **{name: refuse(f"{home.__name__}.{name}") for name in names}) for home, names in HOMES.items())]
        for part in self.parts:
            part.__enter__()

    def __exit__(self, *exc: object) -> None:
        for part in reversed(self.parts):
            part.__exit__(*exc)


def norm(value: object) -> object:
    if value is CONFIG:
        return "CONFIG"
    if id(value) in NAMES:
        return NAMES[id(value)]
    if isinstance(value, Path):
        return str(value)
    if callable(value):
        return "SAY"
    return value


class Turns(list):
    """Answers handed out one per call, in order."""


def stand_ins(log: list, answers: dict) -> dict:
    def seam(name: str):
        def call(*args: object, **kwargs: object) -> object:
            REACHED.add(name)
            log.append([name, [norm(a) for a in args], {k: norm(v) for k, v in sorted(kwargs.items())}])
            got = answers[name]
            return got.pop(0) if isinstance(got, Turns) else (list(got) if isinstance(got, list) else got)
        return call
    return {name: seam(name) for reads in SEAMS.values() for name in reads}


def run(fn: str, kw: dict, answers: dict, *, defaults: bool) -> object:
    """`defaults`: pass nothing but the config, so the definition-time runner/signaller/print are the ones used (print captured)."""
    log: list = []
    said: list = []
    stdout = io.StringIO()
    if not defaults:
        kw = {**kw, "print_func": lambda line: said.append(line) or log.append(["say"])}
    with contained(), patched(t, **stand_ins(log, answers)), contextlib.redirect_stdout(stdout):
        try:
            got = getattr(m, fn)(CONFIG, config_path=CONFIG_PATH, **({} if defaults else kw))
        except AssertionError:
            raise
        except BaseException as exc:  # noqa: BLE001 -- whatever a mutant raises is an answer to compare
            got = repr(exc)
    return {"answer": got, "said": said, "stdout": stdout.getvalue(), "calls": log}


def cases() -> dict:
    """The cases `gold405.py` measured, built the same way."""
    out = {}
    for window, sessions, residual, listener, board in itertools.product((False, True), repeat=5):
        answers = {**BASE, "close_presentation_window": ["the window would not close"] if window else [], "stop_project": 1 if sessions else 0,
                   "contain_residual_project_processes": ["pid 41 escaped"] if residual else [],
                   "stop_owner_listener": ["the listener would not stop"] if listener else [],
                   "_board_system_unit_action": ["the board would not stop"] if board else []}
        label = ",".join(n for n, f in zip(("window", "sessions", "residual", "listener", "board"), (window, sessions, residual, listener, board)) if f) or "none"
        out[f"suspend:fails {label}"] = ("suspend_tenant", {"gui_user": "syrd405-viewer", "runner": RUNNER, "proc_root": PROC, "signaller": SIGNALLER}, answers, False)
    out["suspend:defaults"] = ("suspend_tenant", {}, {**BASE, "close_presentation_window": [], "stop_project": 0, "contain_residual_project_processes": [],
                                                      "stop_owner_listener": [], "_board_system_unit_action": []}, True)
    out["suspend:defaults, all failing"] = ("suspend_tenant", {}, {**BASE, "close_presentation_window": ["w"], "stop_project": 2,
                                                                   "contain_residual_project_processes": ["r"], "stop_owner_listener": ["l"],
                                                                   "_board_system_unit_action": ["b"]}, True)

    def resume(label, *, staging=(), active=(), start=(), state="inactive", listener=(), defaults=False):
        out[f"resume:{label}"] = ("resume_tenant", {"runner": RUNNER},
                                  {**BASE, "ensure_staged_role_tooling": list(staging), "board_system_unit_is_active": Turns(active),
                                   "_board_system_unit_action": list(start), "capture_listener_state": state, "start_owner_listener": list(listener)}, defaults)
    for staging in ((), ("the bundle is not staged", "the helper is stale")):
        for first in (True, False):
            for start in ((), ("the board would not start",)):
                for second in (True, False):
                    for state in ("active", "inactive", "failed"):
                        for listener in ((), ("the listener would not start",)):
                            label = (f"staging {'fails' if staging else 'ok'}; board {'active' if first else 'inactive'}; start {'fails' if start else 'ok'}; "
                                     f"then {'up' if second else 'down'}; listener {state}; listener start {'fails' if listener else 'ok'}")
                            resume(label, staging=staging, active=(first, second), start=start, state=state, listener=listener)
    resume("defaults", active=(False, True), defaults=True)
    resume("defaults, board already up and listener active", active=(True, True), state="active", defaults=True)
    return out


def test_the_guard_itself_refuses_a_spawn_a_signal_and_each_step_past_the_launcher() -> None:
    attempts = [lambda: subprocess.run(["true"]), lambda: subprocess.Popen(["true"]), lambda: os.kill(os.getpid(), 0),
                *(lambda home=home, name=name: getattr(home, name)(CONFIG) for home, names in HOMES.items() for name in names)]
    for attempt in attempts:
        with contained():
            try:
                attempt()
            except AssertionError as exc:
                refused = " was called: " in str(exc)
            else:
                refused = False
        check(refused, "the guard refuses a spawn, a signal, and each step's own definition")


