def test_the_module_loads_nothing_of_switchyards_at_import() -> None:
    result = python("import sys, scripts.tenant_suspension as m; "
                    "print(sorted(n for n in sys.modules if n.startswith('scripts.') and n != m.__name__))")
    check(result.returncode == 0 and result.stdout.strip() == "[]",
          f"it imports on its own and loads nothing else of Switchyard's: {result.stdout}{result.stderr[-400:]}")


def test_either_import_order_gives_one_set_of_objects_and_the_defaults() -> None:
    for order in (("scripts.tenant_suspension", "scripts.team_launcher"), ("scripts.team_launcher", "scripts.tenant_suspension")):
        result = python("import importlib, inspect, os, subprocess; "
                        f"[importlib.import_module(n) for n in {order!r}]; "
                        "import scripts.team_launcher as t, scripts.tenant_suspension as m; "
                        "s = inspect.signature(m.suspend_tenant).parameters; r = inspect.signature(m.resume_tenant).parameters; "
                        f"print(all(getattr(t, n) is getattr(m, n) for n in {MOVED!r}), "
                        "s['runner'].default is subprocess.run and s['signaller'].default is os.kill and s['print_func'].default is print "
                        "and s['gui_user'].default == '' and s['proc_root'].default is None "
                        "and r['runner'].default is subprocess.run and r['print_func'].default is print "
                        "and list(s) == ['config', 'config_path', 'gui_user', 'runner', 'proc_root', 'signaller', 'print_func'] "
                        "and list(r) == ['config', 'config_path', 'runner', 'print_func'], "
                        "not hasattr(m, 'ProjectConfig') and not hasattr(m, 'launcher') and not hasattr(m, 'stop_project'))")
        check(result.stdout.strip() == "True True True", f"{' then '.join(order)}: {result.stdout}{result.stderr[-600:]}")
    check(m.os is os and m.subprocess is subprocess and m.Path is Path, "the standard-library names are the module's own")


def test_the_seams_read_through_the_launcher_and_nothing_bound() -> None:
    tree = ast.parse((ROOT / "scripts" / "tenant_suspension.py").read_text(encoding="utf-8"))
    for name in MOVED:
        node = next(n for n in tree.body if getattr(n, "name", None) == name)
        through: dict[str, int] = {}
        for x in ast.walk(node):
            if isinstance(x, ast.Attribute) and isinstance(x.value, ast.Name) and x.value.id == "launcher":
                through[x.attr] = through.get(x.attr, 0) + 1
        expected = SEAMS[name]
        check(through == expected, f"{name}: each launcher name read through it exactly as often as before: {through}")
        imports = [ast.unparse(x) for x in ast.walk(node) if isinstance(x, (ast.Import, ast.ImportFrom))]
        first = 1 if ast.get_docstring(node) is not None else 0
        check(imports == ["from scripts import team_launcher as launcher"] and ast.unparse(node.body[first]) == imports[0],
              f"{name}: the launcher imported once, first thing when it runs: {imports}")
        skip = {id(y) for part in [node.returns, *(a.annotation for a in node.args.args + node.args.kwonlyargs), *node.args.defaults,
                                   *[d for d in node.args.kw_defaults if d],
                                   *(x.annotation for x in ast.walk(node) if isinstance(x, ast.AnnAssign))] if part is not None for y in ast.walk(part)}
        bare = sorted({x.id for x in ast.walk(node) if isinstance(x, ast.Name) and isinstance(x.ctx, ast.Load) and x.id in expected and id(x) not in skip})
        check(bare == [], f"{name}: none of them read past it: {bare}")
        defaults = [ast.unparse(d) for d in node.args.kw_defaults if d is not None]
        check([d for d in defaults if d in ("subprocess.run", "os.kill", "print")] == (["subprocess.run", "os.kill", "print"] if name == "suspend_tenant"
                                                                                       else ["subprocess.run", "print"]),
              f"{name}: the runner, signaller and print defaults are bound when it is defined: {defaults}")
    top = [ast.unparse(n) for n in tree.body if isinstance(n, (ast.Import, ast.ImportFrom))]
    tc = [ast.unparse(n) for n in tree.body if isinstance(n, ast.If)]
    check(top == ["from __future__ import annotations", "import os", "import subprocess", "from pathlib import Path",
                  "from typing import TYPE_CHECKING, Any, Callable"] and tc == ["if TYPE_CHECKING:\n    from scripts.team_launcher import ProjectConfig"],
          f"only the standard library at the top, and the annotation's type under TYPE_CHECKING: {top} {tc}")
    order = [n.name for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef, ast.Assign))]
    check(order == list(MOVED), f"the two in the launcher's order, and nothing else: {order}")


def test_the_launcher_reexports_the_two_and_dispatches_through_them() -> None:
    tree = ast.parse((ROOT / "scripts" / "team_launcher.py").read_text(encoding="utf-8"))
    imports = [n for n in tree.body if isinstance(n, ast.ImportFrom) and n.module == "scripts.tenant_suspension"]
    check(len(imports) == 1 and sorted(a.name for a in imports[0].names) == sorted(MOVED) and all(a.asname is None for a in imports[0].names),
          "one explicit import of exactly the two, unaliased")
    check(imports[0].lineno < min(n.lineno for n in tree.body if isinstance(n, (ast.FunctionDef, ast.ClassDef))),
          "at the top, above every definition that could read them")
    defined = {getattr(n, "name", None) for n in tree.body} | {x.id for n in tree.body if isinstance(n, ast.Assign) for x in n.targets if isinstance(x, ast.Name)}
    # A neighbour stays reachable on the launcher: defined there, or -- once a later slice moves it on -- re-exported there, unaliased.
    exported = {a.name for n in tree.body if isinstance(n, ast.ImportFrom) and (n.module or "").startswith("scripts.")
                for a in n.names if a.asname is None}
    check(not defined & set(MOVED) and {"_plan_data_from_config", "stop_project", "switchyard_main"} <= defined | exported,
          "the launcher defines neither, and keeps its neighbours and its dispatcher, its own or re-exported")
    calls: dict = {}
    for fn in launcher_body(ROOT, tree):
        if isinstance(fn, ast.FunctionDef):
            for x in ast.walk(fn):
                if isinstance(x, ast.Call) and ast.unparse(x.func).split(".")[-1] in MOVED:
                    calls.setdefault(fn.name, {}).setdefault(ast.unparse(x.func), 0)
                    calls[fn.name][ast.unparse(x.func)] += 1
    check(calls == DISPATCH, f"the dispatcher calls both by its own globals, as often as before: {calls}")


# --- behaviour -----------------------------------------------------------------------------------------------------


def test_every_suspension_and_resume_is_the_baselines() -> None:
    measured = cases()
    check(sorted(measured) == sorted(GOLDEN), "every measured case is asserted, and nothing else")
    for label, (fn, kw, answers, defaults) in measured.items():
        got = run(fn, kw, answers, defaults=defaults)
        check(got == GOLDEN[label], f"{label}: the baseline's answer, messages and every call in order: {got}")


def test_a_suspension_attempts_every_step_and_a_resume_stops_at_its_boundary() -> None:
    every = [c[0] for c in GOLDEN["suspend:fails window,sessions,residual,listener,board"]["calls"]]
    check(every == ["close_presentation_window", "stop_project", "contain_residual_project_processes", "stop_owner_listener", "_board_system_unit_action"],
          f"with every step failing, a suspension still attempts every one, in order: {every}")
    staged = [c[0] for c in GOLDEN["resume:staging fails; board inactive; start ok; then up; listener inactive; listener start ok"]["calls"]]
    check(staged == ["ensure_staged_role_tooling"], f"unstaged tooling: nothing after it is asked or started: {staged}")
    down = [c[0] for c in GOLDEN["resume:staging ok; board inactive; start ok; then down; listener inactive; listener start ok"]["calls"]]
    check("capture_listener_state" not in down and "start_owner_listener" not in down, f"a board that did not come up: no listener: {down}")


def test_every_launcher_seam_is_reached() -> None:
    expected = {name for reads in SEAMS.values() for name in reads}
    check(REACHED == expected, f"a stand-in on the launcher reached every seam: missing {sorted(expected - REACHED)}, extra {sorted(REACHED - expected)}")


STRUCTURE = ("test_the_module_loads_nothing_of_switchyards_at_import", "test_either_import_order_gives_one_set_of_objects_and_the_defaults",
             "test_the_seams_read_through_the_launcher_and_nothing_bound", "test_the_launcher_reexports_the_two_and_dispatches_through_them")
LAST = ("test_every_launcher_seam_is_reached",)


def main() -> int:
    names = sorted(name for name, value in globals().items() if name.startswith("test_") and callable(value))
    for name in [*STRUCTURE, *(name for name in names if name not in STRUCTURE + LAST), *LAST]:
        globals()[name]()
    print(f"tenant_suspension_boundary_test: {CHECKS} checks ok")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
